  Map<String, dynamic> toJson() => {
        'blockedAt': blockedAt,
        ...switch (blockedDueToOverageType) {
          SdkPresent<AuthUserSoftBlockBlockedDueToOverageType>(
            value: final value
          ) =>
            {
              'blockedDueToOverageType': value.toJson(),
            },
          _ => const <String, dynamic>{},
        },
        'reason': reason.toJson(),
        ...switch (unpauseAt) {
          SdkPresent<double>(value: final value) => {
              'unpauseAt': value,
            },
          _ => const <String, dynamic>{},
        },
      };
}
